# backend/llm/prompt.py
from typing import List, Dict, Any
import logging

logger = logging.getLogger(__name__)

class PromptBuilder:
    """
    Constructs structured prompts for the LLM report generator.
    Ensures all necessary clinical context, predictions, and safety disclaimers are included.
    """
    
    MEDICAL_DISCLAIMER = (
        "⚠️ MEDICAL DISCLAIMER: This report is generated by an AI research prototype for clinical decision support ONLY. "
        "It is NOT a substitute for professional medical advice, diagnosis, or treatment. "
        "All findings must be verified by a licensed healthcare provider."
    )

    @staticmethod
    def build_system_prompt() -> str:
        return f"""You are an expert AI Clinical Decision Support Assistant. 
Your task is to generate a professional, structured, and concise medical summary report based on multimodal AI analysis.

RULES:
1. ALWAYS begin and end your report with the following exact disclaimer:
"{PromptBuilder.MEDICAL_DISCLAIMER}"
2. Use clear, professional medical terminology, but remain concise.
3. Do NOT invent symptoms, findings, or references not provided in the context.
4. Format your response strictly in Markdown with the following headers:
   - ## 📋 Patient Summary
   - ## 🔬 AI Diagnostic Findings
   - ## 🧠 Model Explainability
   - ## 📚 Clinical References (from retrieved context)
   - ## ⚠️ Disclaimer
"""

    @staticmethod
    def build_user_prompt(
        patient_data: Dict[str, Any],
        predictions: Dict[str, Any],
        explainability: Dict[str, Any],
        rag_context: List[Dict[str, str]]
    ) -> str:
        # 1. Format Patient Data
        patient_str = f"Age: {patient_data.get('age', 'N/A')}, Gender: {patient_data.get('gender', 'N/A')}\n"
        patient_str += f"Symptoms: {patient_data.get('symptoms', 'None provided')}\n"
        patient_str += f"Vitals: {patient_data.get('vitals', {})}\n"
        patient_str += f"History: {', '.join(patient_data.get('prior_conditions', ['None']))}"

        # 2. Format Predictions
        top_diseases = predictions.get("final_diseases", ["Unknown"])
        confidence = predictions.get("confidence_score", 0.0)
        pred_str = f"Top Predicted Conditions: {', '.join(top_diseases)}\n"
        pred_str += f"Multimodal Fusion Confidence Score: {confidence:.2%}\n"
        pred_str += "Individual Modality Contributions:\n"
        pred_str += f"  - Image (ViT) Top: {max(predictions.get('image_prediction', {}), key=predictions['image_prediction'].get, default='N/A')}\n"
        pred_str += f"  - Text (ClinicalBERT) Top: {max(predictions.get('text_prediction', {}), key=predictions['text_prediction'].get, default='N/A')}"

        # 3. Format Explainability (Simplified for LLM)
        exp_str = ""
        if "tabular_shap" in explainability:
            top_shap = sorted(explainability["tabular_shap"].items(), key=lambda x: abs(x[1]), reverse=True)[:3]
            exp_str += f"- **Tabular (SHAP)**: The top contributing structured features were: {', '.join([f'{k} (impact: {v})' for k, v in top_shap])}.\n"
        if "text_attention" in explainability:
            top_words = sorted(explainability["text_attention"], key=lambda x: x["attention_weight"], reverse=True)[:3]
            exp_str += f"- **Symptom Text (Attention)**: The model focused most heavily on the terms: '{', '.join([w['token'] for w in top_words])}'.\n"
        exp_str += "- **Image (Grad-CAM)**: A heatmap has been generated highlighting the regions of interest in the medical image (provided separately to the frontend)."

        # 4. Format RAG Context
        context_str = ""
        for i, chunk in enumerate(rag_context):
            source = chunk.get("metadata", {}).get("source", "Unknown Source")
            text = chunk.get("text", "")[:300] # Truncate to avoid token overflow
            context_str += f"[{i+1}] Source: {source}\nSnippet: {text}...\n\n"

        return f"""
### PATIENT DATA
{patient_str}

### AI PREDICTIONS
{pred_str}

### MODEL EXPLAINABILITY
{exp_str}

### RETRIEVED CLINICAL CONTEXT
{context_str if context_str else "No specific clinical guidelines were retrieved."}

Please generate the structured clinical report based on this data.
"""